SELECT 'inventory' tbl, warehouse_code, location_code, sku_code, batch_no, qty, freeze_qty FROM jim_wms_inventory.wms_inventory WHERE sku_code='SKU-001'; SELECT 'log' tbl, id, sku_code, business_type, business_no, change_qty, before_qty, after_qty, biz_key FROM jim_wms_inventory.wms_inventory_log ORDER BY id; SELECT 'order' tbl, outbound_no, order_type, status FROM jim_wms_outbound.wms_outbound_order WHERE outbound_no='OUT1794895803002'; SELECT 'task' tbl, outbound_no, sku_code, status, change_qty, retry_count, next_retry_time, (last_error IS NULL) AS last_error_is_null, last_error FROM jim_wms_outbound.wms_outbound_stock_task WHERE outbound_no='OUT1794895803002';
